export enum SupportedDatastores {
    s3 = 's3',
}
/**
 *
 * This Class represents the access information and control data structure for Datastore based Measurement solutions
 * Specifically this is the access information needed for S3-based usage ingestion from a customer account.
 * */
export class DatastoreAccessInformation {
    /**
     * Underlying datastore platform. Default is s3.
     */
    @Matches(
        `^${Object.values(SupportedDatastores)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsOptional()
    @ApiProperty({
        enum: SupportedDatastores,
        isArray: false,
        required: false,
        examples: ['s3'],
    })
    public platform?: SupportedDatastores | string;

    /**
     * Customer AWS account ID. Required.
     * @example "623673123435"
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({ example: '623673123435' })
    public accountId: string;

    /**
     * AWS region for the IAM role and buckets. Default is us-east-1.
     * @example "us-east-1"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, example: 'us-east-1' })
    public region?: string;

    /**
     * IAM role ARN generated by Enterprise for customer uploads.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public iamRoleArn?: string;

    /**
     * External ID required when assuming the generated IAM role.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public externalId?: string;

    /**
     * S3 URI prefix for usage ingestion.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public ingestion?: string;

    /**
     * S3 URI prefix for the dead-letter queue.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public dlq?: string;

    @ApiHideProperty()
    @IsOptional()
    public businessID?: string;

    @ApiHideProperty()
    @IsOptional()
    public measurementId?: string;

    constructor(datastoreAccessInformation: Partial<DatastoreAccessInformation>) {
        if (datastoreAccessInformation) {
            const {
                accountId,
                platform,
                region,
                iamRoleArn,
                externalId,
                ingestion,
                dlq,
                businessID,
                measurementId,
            } = datastoreAccessInformation;
            this.accountId = accountId;
            this.platform = platform ? platform : SupportedDatastores.s3;
            this.region = region ? region : process.env.AWS_REGION || 'us-east-1';
            this.iamRoleArn = iamRoleArn;
            this.externalId = externalId;
            this.ingestion = ingestion;
            this.dlq = dlq;
            this.businessID = businessID;
            this.measurementId = measurementId;
        }
    }

    public static transformer(datastoreAccessInformation: DatastoreAccessInformation, influxPoint: Point) {
        if (datastoreAccessInformation) {
            const { platform, accountId, region, iamRoleArn, externalId, ingestion, dlq } =
                datastoreAccessInformation;
            if (platform) influxPoint.tag('platform', platform);
            if (accountId) influxPoint.tag('accountId', accountId);
            if (region) influxPoint.tag('region', region);
            if (iamRoleArn) influxPoint.tag('iamRoleArn', iamRoleArn);
            if (externalId) influxPoint.tag('externalId', externalId);
            if (ingestion) influxPoint.tag('ingestion', ingestion);
            if (dlq) influxPoint.tag('dlq', dlq);
        }
        return influxPoint;
    }

    public static dbModelToEntity({
        platform,
        accountId,
        region,
        iamRoleArn,
        externalId,
        ingestion,
        dlq,
        businessID,
        measurementId,
    }: {
        [x: string]: any;
    }) {
        return new DatastoreAccessInformation({
            platform,
            accountId,
            region,
            iamRoleArn,
            externalId,
            ingestion,
            dlq,
            businessID,
            measurementId,
        });
    }

    private static buildTrustPolicy(accountId: string, externalId: string) {
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${accountId}:root`,
                    },
                    Action: 'sts:AssumeRole',
                    Condition: {
                        StringEquals: {
                            'sts:ExternalId': externalId,
                        },
                    },
                },
            ],
        };
    }

    private static buildInlinePolicy(businessID: string) {
        const ingestionBucket = process.env.DB_MEASUREMENT_BUCKET_NAME;
        const dlqBucket = process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME;
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Effect: 'Allow',
                    Action: ['s3:PutObject', 's3:GetObject', 's3:AbortMultipartUpload', 's3:ListMultipartUploadParts'],
                    Resource: [
                        `arn:aws:s3:::${ingestionBucket}/${businessID}/*`,
                        `arn:aws:s3:::${dlqBucket}/${businessID}/*`,
                    ],
                },
                {
                    Effect: 'Allow',
                    Action: ['s3:ListBucket', 's3:ListBucketMultipartUploads'],
                    Resource: [`arn:aws:s3:::${ingestionBucket}`, `arn:aws:s3:::${dlqBucket}`],
                    Condition: {
                        StringLike: {
                            's3:prefix': [`${businessID}/*`, businessID],
                        },
                    },
                },
            ],
        };
    }

    public static async setupAccess(
        dbAccessInformation: DatastoreAccessInformation,
        measurementId: string,
        businessID?: string
    ) {
        const bizId = businessID || dbAccessInformation.businessID;
        const platform = (dbAccessInformation.platform as SupportedDatastores) || SupportedDatastores.s3;
        const region = dbAccessInformation.region || process.env.AWS_REGION || 'us-east-1';
        const accountId = dbAccessInformation.accountId;

        if (!accountId) {
            throw new BadRequestException('accountId is required for datastoreBased measurement');
        }
        if (!bizId) {
            throw new BadRequestException('businessID is required for datastoreBased measurement');
        }
        if (platform.toLowerCase() !== SupportedDatastores.s3) {
            throw new BadRequestException(`Unsupported datastore platform: ${platform}`);
        }

        const roleName = `datastore-${bizId}-${measurementId}`;
        const externalId = randomUUID();
        const ingestionBucket = process.env.DB_MEASUREMENT_BUCKET_NAME;
        const dlqBucket = process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME;
        const ingestion = `s3://${ingestionBucket}/${bizId}/`;
        const dlq = `s3://${dlqBucket}/${bizId}/`;

        const iam = new IAMClient({ region });
        try {
            const createRoleResp = await iam.send(
                new CreateRoleCommand({
                    RoleName: roleName,
                    AssumeRolePolicyDocument: JSON.stringify(
                        DatastoreAccessInformation.buildTrustPolicy(accountId, externalId)
                    ),
                    Description: `Enterprise datastore ingestion role for business ${bizId} measurement ${measurementId}`,
                })
            );

            await iam.send(
                new PutRolePolicyCommand({
                    RoleName: roleName,
                    PolicyName: `${roleName}-policy`,
                    PolicyDocument: JSON.stringify(DatastoreAccessInformation.buildInlinePolicy(bizId)),
                })
            );

            dbAccessInformation.platform = platform;
            dbAccessInformation.region = region;
            dbAccessInformation.externalId = externalId;
            dbAccessInformation.iamRoleArn = createRoleResp.Role?.Arn;
            dbAccessInformation.ingestion = ingestion;
            dbAccessInformation.dlq = dlq;
            dbAccessInformation.businessID = bizId;
            dbAccessInformation.measurementId = measurementId;
            dbAccessInformation.accountId = accountId;

            return dbAccessInformation;
        } catch (e) {
            if (e?.name === 'MalformedPolicyDocument' || e?.Code === 'MalformedPolicyDocument') {
                throw new BadRequestException(`accountId: ${accountId} is invalid`);
            }
