        const iam = new IAMClient({ region: region || process.env.AWS_REGION || 'us-east-1' });
        try {
            await iam.send(
                new UpdateAssumeRolePolicyCommand({
                    RoleName: roleName,
                    PolicyDocument: JSON.stringify(
