                    ),
                })
            );
            return dbAccessInformation;
        } catch (e) {
            if (e?.name === 'MalformedPolicyDocument' || e?.Code === 'MalformedPolicyDocument') {
                throw new BadRequestException(`accountId: ${accountId} is invalid`);
            }
            throw e;
        }
    }
}

