@ApiTags('Usage')
@Controller('usage')
export class PrivateAPIUsageController {
    private static readonly logger = new Logger(PrivateAPIUsageController.name);
    constructor(private readonly usageService: UsageService) {}

    /**
     * Collect usage data by API-based method.
     * See <a href="https://docs.enterprise.tech/measure-usage-and-collect-data/measure-and-collect-usage-data-at-production-scale">Measure and Collect Usage Data At Production Scale</a>
     * for full documentation on Enterprise <b>Usage Measurement and Collection</b>.
     * @param createUsageDto
     * @param request
     */
    @ApiCreatedResponse({
        status: 201,
        description: 'OK',
        type: BasicResponseDTO,
    })
    @ApiBadRequestResponse({
        status: 400,
        description: 'Bad Request',
        type: BasicResponseDTO,
    })
    @ApiOperation({ operationId: 'Collect usage data' })
    @UseGuards(AuthGuard('jwt'))
    @Post()
    create(@Body() createUsageDto: CreateUsageDto, @Req() request: Request) {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        const { businessID } = request.user;
        return this.usageService.create({ ...createUsageDto, businessID });
    }

    @UseGuards(LogGaurd, AuthGuard('jwt'))
    @Post('db')
    async dbUsage(@Body() createUsageDto) {
        PrivateAPIUsageController.logger.log('Starting DB Usage Endpoint execution');

        const { message, s3Key } = createUsageDto || {};
        try {
            if (!s3Key) {
                throw new Error('s3Key is required');
            }
            let relativeKey = s3Key;
            const s3UriMatch = String(s3Key).match(/^s3:\/\/[^/]+\/(.+)$/);
            if (s3UriMatch) {
                relativeKey =<REDACTED>
            }
            const [businessID] = relativeKey.split('/');
            if (!businessID) {
                throw new Error('Unable to derive businessID from s3Key');
            }
            const parsed = typeof message === 'string' ? JSON.parse(message) : message;
            if (!parsed || typeof parsed !== 'object') {
                throw new Error('message must be a valid usage JSON record');
            }
            return await this.usageService.create({ ...parsed, businessID });
        } catch (error) {
            PrivateAPIUsageController.logger.error('DB Usage processing failed', error);
            await StandardMeasurementEntity.publishFailureToDLQ({
                message,
                s3Key,
                error,
            });
            throw error;
        }
    }
}

